	if got := len(bytes.Split(bytes.TrimSpace(raw), []byte("\n"))); got != 1 {
		t.Fatalf("ledger line count = %d, want 1", got)
	}
}

func runBenchCLI(t *testing.T, repoRoot string, args ...string) (int, string) {
	t.Helper()

